						try{/* Premium Calculator — "Check premium without providing details" link
   Appended inline at the end of the ".agreement p" consent text ("…from Axis Max Life. <link>").
   Inherits the consent text's grey styling; only an underline marks it as a link. */
(function () {
  var ID = 'amli-no-details-link';
  var LINK_URL = 'https://www.axismaxlife.com/insurance-calculators'; // where the link goes
  var TEXT = 'Check premium without providing details';
  // Gate: run only on the premium-calculator page, and never on stage environments.
  // NOTE: /term-insurance-plans client-side redirects here, so location.href
  // settles on /premium-calculator — gating on that path is what actually matches.
  var TARGET_URL = 'https://www.axismaxlife.com/term-insurance-plans/premium-calculator';
  function urlAllowed() {
    var href = window.location.href;
    return href.indexOf(TARGET_URL) !== -1 && href.toLowerCase().indexOf('stage') === -1;
  }
  function inject() {
    if (!urlAllowed()) {            // wrong page (or a stage host) — clean up and stay out
      var stale = document.getElementById(ID);
      if (stale) stale.remove();
      return;
    }
    var consent = document.querySelector('.agreement p');
    if (!consent) return;
    var existing = document.getElementById(ID);
    if (existing && consent.contains(existing)) return; // already in place
    if (existing) existing.remove();                    // stale node from a previous route
    var a = document.createElement('a');
    a.id = ID;
    a.href = LINK_URL;
    a.textContent = TEXT;
    // same grey as the consent copy (font/size/colour inherited from ".agreement p")
    a.style.cssText = 'color:inherit;font:inherit;text-decoration:underline;text-underline-offset:2px;cursor:pointer;margin-left:4px;';
    consent.appendChild(a);
  }
  // singleton heartbeat: survives SPA route changes / React re-renders
  if (window.__amliNoDetailsLinkTimer) clearInterval(window.__amliNoDetailsLinkTimer);
  inject();
  window.__amliNoDetailsLinkTimer = setInterval(inject, 500);
})();
}catch(e) {VWO._.vAEH(e);}
