/* VWO variation v2 - Savings lead page, NRI = Yes: default residence country = United States.
 * Also hides Email on NRI = Yes and locks the mobile country code.
 * Mobile shows flag-only options, so options are matched by flag class.
 * NRI preselected (returning visitor): re-clicks the dropdown until it really opens. */
(function () {
  var DEFAULT_COUNTRY = 'United States';
  var DEFAULT_FLAG = 'flagIcon-united-states';

  var NRI_RADIO = '#nricitizenship';
  var CR_BUTTON = '.leadCountryOfResidence-select';
  var CR_LIST = '#leadCountryOfResidence-select';
  var CR_OPTION = CR_LIST + ' a.custom-select-option';
  var CR_LABEL = '.phone-code-custom-select .cr-country-code';
  var PHONE_BUTTON = '.phoneNumber-select';
  var EMAIL = '#email';
  var LOG = '[nri-variation]';

  if (window.__nriVariationV2) return;
  window.__nriVariationV2 = true;

  var html = document.documentElement;
  var target = DEFAULT_COUNTRY.trim().toLowerCase();
  var userPicked = false;

  var style = document.createElement('style');
  style.textContent = [
    'html.nri-busy ' + CR_LIST + '{display:none!important}',
    'html.nri-busy ' + CR_BUTTON + ' .flagIcon,html.nri-busy ' + CR_LABEL +
      ',html.nri-busy ' + PHONE_BUTTON + '{visibility:hidden!important}',
    '.nri-hide{display:none!important}',
    PHONE_BUTTON + '{pointer-events:none!important;cursor:default!important}',
    PHONE_BUTTON + ' .chevron-icon{display:none!important}',
    '#phoneNumber-select{display:none!important}'
  ].join('\n');
  document.head.appendChild(style);

  document.addEventListener('click', function (e) {
    if (e.isTrusted && e.target.closest && e.target.closest(CR_OPTION)) userPicked = true;
  }, true);

  function isTarget(el) {
    if (!el) return false;
    if (el.querySelector('.' + DEFAULT_FLAG) || (el.classList && el.classList.contains(DEFAULT_FLAG))) return true;
    return el.textContent.trim().toLowerCase() === target;
  }

  function alreadySet() {
    var btn = document.querySelector(CR_BUTTON);
    var label = document.querySelector(CR_LABEL);
    return isTarget(btn) || (label && label.textContent.trim().toLowerCase() === target);
  }

  function findOption() {
    var opts = document.querySelectorAll(CR_OPTION);
    for (var i = 0; i < opts.length; i++) if (isTarget(opts[i])) return opts[i];
    return null;
  }

  function closeList() {
    document.body.dispatchEvent(new MouseEvent('mousedown', { bubbles: true }));
    document.body.dispatchEvent(new MouseEvent('click', { bubbles: true }));
  }

  var safety, running = false;
  function finish() {
    clearTimeout(safety);
    running = false;
    if (document.querySelector(CR_LIST)) closeList();
    var a = document.activeElement;
    if (a && a.closest && a.closest('.phone-code-custom-select') && a.blur) a.blur();
    var n = 0;
    (function clear() {
      if (document.querySelector(CR_LIST) && n++ < 20) { closeList(); return setTimeout(clear, 25); }
      html.classList.remove('nri-busy');
    })();
  }

  function autoSelect(btn) {
    if (running || btn.getAttribute('data-nri-default')) return;
    btn.setAttribute('data-nri-default', '1');
    if (userPicked || alreadySet()) return;
    running = true;

    html.classList.add('nri-busy');
    safety = setTimeout(function () { html.classList.remove('nri-busy'); }, 6500);

    setTimeout(function () {
      var t0 = Date.now(), lastClick = 0;
      (function pick() {
        var cur = document.querySelector(CR_BUTTON) || btn;
        if (userPicked || alreadySet()) return finish();
        var opt = findOption();
        if (opt) { opt.click(); return finish(); }
        if (!document.querySelector(CR_LIST) && Date.now() - lastClick > 400) {
          lastClick = Date.now();
          cur.click();
        }
        if (Date.now() - t0 < 6000) return setTimeout(pick, 30);
        console.warn(LOG, 'Option "' + DEFAULT_COUNTRY + '" not found');
        finish();
      })();
    }, 0);
  }

  function hideEmail(on) {
    var email = document.querySelector(EMAIL);
    if (!email) return;
    var col = email.closest('[class*="md:w-1/2"]');
    var box = col && col.querySelectorAll('input').length === 1 ? col : email.closest('.floating-label-wrap') || email;
    box.classList.toggle('nri-hide', on);
  }

  function run() {
    var radio = document.querySelector(NRI_RADIO);
    var yes = radio ? radio.checked : false;
    var btn = document.querySelector(CR_BUTTON);
    if (yes && btn) autoSelect(btn);
    hideEmail(yes);
  }

  new MutationObserver(run).observe(document.body, { childList: true, subtree: true });
  document.addEventListener('change', run, true);
  run();
})();
